import{_ as o,o as t,c as s,a2 as a}from"./chunks/framework.BXzK3EA4.js";const g=JSON.parse('{"title":"Version 2.0.0.8 Released","description":"","frontmatter":{},"headers":[],"relativePath":"change-log/release/version-2.0.0.8-released.md","filePath":"change-log/release/version-2.0.0.8-released.md"}'),i={name:"change-log/release/version-2.0.0.8-released.md"};function n(r,e,d,c,l,p){return t(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="version-2-0-0-8-released" tabindex="-1">Version 2.0.0.8 Released <a class="header-anchor" href="#version-2-0-0-8-released" aria-label="Permalink to &quot;Version 2.0.0.8 Released&quot;">​</a></h1><p><strong>Date: 1st May 2026</strong></p><p><strong>GTT Orders for Zerodha &amp; Dhan, Telegram <code>/StopPython</code> Command, Historify Parquet Aggregation Fix, Codebase-Wide bare-except Sweep &amp; Critical Docker Upgrade Hotfix</strong></p><p>This release covers <strong>6 commits</strong> since v2.0.0.7. The headline addition is end-to-end GTT (Good Till Triggered) order support for Zerodha and Dhan via four new endpoints — <code>placegttorder</code>, <code>modifygttorder</code>, <code>cancelgttorder</code>, <code>gttorderbook</code> — currently in pilot, with rollout to the remaining supported brokers planned for upcoming releases. Alongside the feature work, this release ships a <strong>critical hotfix for Docker upgrades from v2.0.0.5 and earlier</strong>: the auto-rotation of publicly-known sample <code>APP_KEY</code> introduced in v2.0.0.6 was crashing the gunicorn worker under Docker because the <code>.env</code> mount was read-only and the rotation could not write its atomic temp file. Any pre-v2.0.0.6 Docker install that left the sample keys in <code>.env</code> was hitting a restart loop on upgrade.</p><hr><p><strong>Highlights</strong></p><ul><li><strong>GTT Order Implementation (Zerodha + Dhan)</strong> — Pilot rollout of <code>/api/v1/placegttorder</code>, <code>/api/v1/modifygttorder</code>, <code>/api/v1/cancelgttorder</code>, <code>/api/v1/gttorderbook</code>. Database migration is mandatory on upgrade. Rollout to all other supported brokers is planned. (#1322)</li><li><strong>Telegram <code>/StopPython</code> command + <code>/closeall</code> enhancement</strong> — Lists running Python strategies inline; new <strong>Close all + Stop strategies</strong> button on <code>/closeall</code> flattens positions and stops every running strategy in one flow. (#1231)</li><li><strong>Historify Parquet export now aggregates computed intervals</strong> — Selecting <code>Parquet</code> with <code>5m</code> / <code>15m</code> / <code>30m</code> / <code>1h</code> / <code>W</code> / <code>M</code> / <code>Q</code> / <code>Y</code> no longer silently downgrades to ZIP. The exporter now uses the same DuckDB time-bucket / daily-aggregation logic the ZIP path has used. (#917)</li><li><strong>Codebase-wide bare-except sweep</strong> — 82 <code>except:</code> clauses across 45 files replaced with <code>except Exception:</code> (#1039). Restores correct shutdown-signal handling under Gunicorn / Docker / systemd; aligns with PEP 8 / Ruff <code>E722</code>.</li><li><strong>🔴 Critical: Docker <code>.env</code></strong> <strong><code>:ro</code> mount removed; <code>APP_KEY</code> auto-rotation no longer crashes legacy Docker installs.</strong> Affects every Docker user upgrading from v2.0.0.5 or earlier.</li></ul><hr><p><strong>Trading APIs</strong></p><p><strong>GTT Orders (#1322)</strong></p><ul><li><code>ce0e4d59</code> — <code>Feat : Gtt Order Implementation. Updated for Dhan and Zerodha</code></li></ul><p>Pilot APIs (currently Zerodha + Dhan; other brokers to follow):</p><ul><li><code>POST /api/v1/placegttorder</code> — place a GTT trigger.</li><li><code>POST /api/v1/modifygttorder</code> — modify trigger / leg parameters.</li><li><code>POST /api/v1/cancelgttorder</code> — cancel an active GTT.</li><li><code>POST /api/v1/gttorderbook</code> — list active triggers.</li></ul><p>Schema highlights: flat place/modify body with <code>triggerprice_sl</code> and <code>triggerprice_tg</code>, <code>MIS</code> rejected, <code>last_price</code> fetched server-side; Dhan SINGLE/OCO mapping with per-leg modify; Zerodha <code>MARKET</code> pricetype auto-converted to MPP-protected <code>LIMIT</code> (Kite GTTs cannot carry MARKET).</p><p>⚠️ <strong>Database migration is mandatory on upgrade.</strong> Run before starting the new build:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade/migrate_all.py</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># or, just for the GTT tables:</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade/migrate_gtt.py</span></span></code></pre></div><p>Adds <code>sandbox_gtt</code> and <code>sandbox_gtt_legs</code> tables and defaults. Sandbox / analyze-mode GTT execution is Phase 3 — analyze mode currently returns <code>501</code> for GTT calls until the in-progress sandbox integration ships.</p><p>API docs: <a href="https://docs.algo.wesoftcorp.com/api-documentation/v1/orders-api/placegttorder" target="_blank" rel="noreferrer">https://docs.algo.wesoftcorp.com/api-documentation/v1/orders-api/placegttorder</a></p><hr><p><strong>Telegram Bot (#1231)</strong></p><ul><li><code>53334a0c</code> — <code>feat(telegram): add /stoppython and &quot;Close all + Stop strategies&quot; action</code></li></ul><p>New <code>/stoppython</code> command snapshots <code>RUNNING_STRATEGIES</code> from <code>blueprints/python_strategy.py</code> and renders one inline button per running strategy plus a <strong>Stop All</strong> button and <strong>Cancel</strong>. Per-strategy and bulk actions both prompt for confirmation before terminating, then call <code>stop_strategy_process()</code> — the same code path the UI&#39;s Stop button uses (<code>SIGTERM</code> → <code>SIGKILL</code> on Linux/Mac, <code>taskkill /F /T</code> on Windows). The strategy-id ↔ button-index map is held in <code>context.user_data[&quot;stoppy_list&quot;]</code> so <code>callback_data</code> stays under Telegram&#39;s 64-byte cap regardless of how long strategy IDs get. If nothing is running, the bot replies <code>ℹ️ No Python strategies running.</code> and exits cleanly.</p><p><code>/closeall</code> confirmation now offers a third button:</p><table tabindex="0"><thead><tr><th>Button</th><th>Action</th></tr></thead><tbody><tr><td>✅ Yes, close all</td><td>(existing) flattens every open position via <code>closeposition</code>.</td></tr><tr><td>⚠️ Close all + Stop strategies</td><td>Closes all positions, then iterates <code>RUNNING_STRATEGIES</code> and terminates each via <code>stop_strategy_process()</code>. Reports a combined summary (positions closed, strategies stopped, failures).</td></tr><tr><td>❌ Cancel</td><td>No-op.</td></tr></tbody></table><p>Help text updated; <code>docs/design/43-telegram-bot/README.md</code> brought back in sync with the actually-registered command names (<code>/orderbook</code>, <code>/tradebook</code>, <code>/chart</code>, <code>/mode</code>, <code>/menu</code>, <code>/link</code>, <code>/unlink</code>).</p><hr><p><strong>Historify (#917)</strong></p><ul><li><code>ee89cf8b</code> — <code>fix(historify): aggregate computed intervals in Parquet export</code></li></ul><p><code>export_to_parquet()</code> previously ran a direct <code>WHERE interval = ?</code> query against <code>market_data</code>, which returns zero rows for any non-storage interval (only <code>1m</code> and <code>D</code> are physically stored — <code>5m / 15m / 30m / 1h</code>, custom intraday like <code>25m / 2h</code>, and <code>W / M / Q / Y</code> are aggregated on the fly). To prevent empty downloads, the historify bulk-export blueprint silently overrode the user&#39;s Parquet selection to ZIP whenever any computed interval was requested — so picking <em>Parquet + 5m</em> produced a <code>.zip</code> of CSVs.</p><p><code>export_to_parquet()</code> now mirrors <code>export_to_zip()</code>&#39;s three-branch interval handling:</p><table tabindex="0"><thead><tr><th>Interval kind</th><th>Source</th><th>Method</th></tr></thead><tbody><tr><td><code>1m</code>, <code>D</code> (storage)</td><td>direct read</td><td>unchanged</td></tr><tr><td><code>5m</code> / <code>15m</code> / <code>30m</code> / <code>1h</code>, custom intraday (<code>25m</code>, <code>2h</code>, …)</td><td>aggregate from <code>1m</code></td><td>DuckDB time-bucket SQL — same query as the ZIP path</td></tr><tr><td><code>W</code> / <code>M</code> / <code>Q</code> / <code>Y</code>, multi-D</td><td>aggregate from <code>D</code></td><td>reuses the existing <code>_get_daily_aggregated_ohlcv()</code></td></tr></tbody></table><p>All symbols&#39; rows go into a single Parquet file with the original schema preserved (<code>symbol, exchange, interval, timestamp, open, high, low, close, volume, oi, datetime</code>). Skipped symbols (missing source data) are surfaced in the response message rather than silently dropped. Compression codec (<code>zstd</code> / <code>snappy</code> / <code>gzip</code> / <code>none</code>) is honored as before.</p><p>The blueprint&#39;s silent ZIP override now applies only to multi-interval requests (legitimate — single-table formats can&#39;t carry per-interval files) and to single-computed CSV/TXT requests (those exporters still use direct queries and need the same treatment in a follow-up).</p><hr><p><strong>Code Quality / Stability (#1039)</strong></p><ul><li><code>b6419a90</code> — <code>fix: replace bare except clauses with except Exception across codebase</code></li></ul><p>82 occurrences across 45 production files in <code>blueprints/</code>, <code>broker/</code> (all 30+ broker integrations), <code>database/</code>, <code>sandbox/</code>, <code>services/</code>, <code>test/</code>, <code>utils/</code>, and <code>websocket_proxy/</code>. Bare <code>except:</code> swallows <code>BaseException</code>, including <code>SystemExit</code> and <code>KeyboardInterrupt</code> — meaning <code>Ctrl+C</code>, <code>SIGTERM</code> from Docker / systemd, and other shutdown signals could be silently absorbed mid-iteration in long-running loops (websocket adapters, Telegram polling, sandbox engine).</p><p>Practical effects:</p><ul><li>Cleaner shutdown under Gunicorn / Docker / systemd — <code>SIGTERM</code> propagates correctly.</li><li><code>MemoryError</code> and other <code>BaseException</code> subclasses now propagate as expected.</li><li><code>database/historify_db.py:_safe_timestamp()</code> additionally upgraded with <code>logger.warning</code> so timestamp conversion failures land in <code>log/errors.jsonl</code> instead of disappearing silently.</li><li>Ruff <code>E722</code> / Flake8 <code>E722</code> no longer fire across the codebase, making future CI lint enforcement viable.</li></ul><p>No behaviour change for ordinary exception flows — call sites still catch <code>Exception</code> and below, exactly as before.</p><hr><p><strong>Security / Docker (Critical)</strong></p><ul><li><code>245403f1</code> — <code>fix(security/docker): unblock APP_KEY/PEPPER auto-rotation under Docker (v2.0.0.8)</code></li></ul><p>v2.0.0.6 introduced an auto-rotation in <code>utils/env_check.py</code> that detects the publicly-known sample <code>APP_KEY</code> / <code>API_KEY_PEPPER</code> (which shipped in <code>.sample.env</code> up to v2.0.0.5, and which <code>install-docker.sh</code> did not rewrite until commit <code>0162ce3a5</code>) and replaces them with fresh secrets on first run. Under Docker, the rotation crashed the gunicorn worker:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>[Tradeboard security]</span></span>
<span class="line"><span>Detected publicly-known APP_KEY/API_KEY_PEPPER in .env, but</span></span>
<span class="line"><span>could not rewrite the file</span></span>
<span class="line"><span>([Errno 13] Permission denied: &#39;/app/utils/../.env.tmp&#39;).</span></span></code></pre></div><p>Two compounding causes:</p><ol><li><code>docker-compose.yaml</code> and the install-script compose templates mounted <code>.env</code> <strong>read-only</strong> (<code>./.env:/app/.env:ro</code>), so the rotation&#39;s atomic <code>.env.tmp</code> write failed with <code>EACCES</code> and <code>sys.exit(1)</code> killed the worker — gunicorn restart loop, container hard-down.</li><li><code>install-docker.sh</code> and <code>install-docker-multi-custom-ssl.sh</code> kept <code>.env</code> at <code>chmod 644</code> owned by host root because the previous <code>:ro</code> mount made <code>chmod 600</code> + root ownership unreadable to the container&#39;s <code>appuser</code> (UID 1000) — see issue #960. With <code>:ro</code> removed, that workaround flipped into a problem: <code>appuser</code> still couldn&#39;t <em>write</em> a root-owned file even if the mount allowed it.</li></ol><p>This affected every Docker user who installed before v2.0.0.6 and pulled the v2.0.0.6+ image — a meaningful slice of the existing Docker install base.</p><p>Fixes shipped:</p><ul><li><strong>Drop <code>:ro</code></strong> from every <code>.env</code> mount so the rotation can write its temp file. Touched: <code>docker-compose.yaml</code>, <code>install/install-docker.sh</code> (compose template), <code>install/install-docker-multi-custom-ssl.sh</code> (compose template), <code>install/docker-run.sh</code>, <code>install/docker-run.bat</code>, <code>docker-build.sh</code>.</li><li><strong><code>chown 1000:1000 .env &amp;&amp; chmod 600 .env</code></strong> in <code>install/install-docker.sh</code>, <code>install/install-docker-multi-custom-ssl.sh</code>, <code>install/docker-run.sh</code> (with Linux/Mac branching). Tighter than the previous mode 644 <em>and</em> Docker-compatible at the same time — only <code>appuser</code> (UID 1000) on the host can read/write, instead of &quot;anyone with read access to the install dir.&quot;</li><li><strong><code>start.sh</code> pre-flight check</strong> before gunicorn launches. If <code>APP_KEY</code> / <code>API_KEY_PEPPER</code> is in the publicly-known compromised set AND <code>.env</code> is not writable from inside the container, prints an unmissable banner with the safe recovery recipe and exits cleanly. Replaces the buried &quot;Permission denied&quot; stack trace with an actionable error.</li></ul><p><strong>Migration for users who hit the crash on Docker:</strong></p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /path/to/tradeboard</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> down</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">git</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pull</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Generate a fresh APP_KEY only — do NOT touch API_KEY_PEPPER on a populated install</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">APP_KEY</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$(</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">python3</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;import secrets; print(secrets.token_hex(32))&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sed</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -i</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;s|^APP_KEY *=.*|APP_KEY = &#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$APP_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;|&quot;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Make .env writable by the container&#39;s appuser (UID 1000)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chown</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> 1000:1000</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> chmod</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 600</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> .env</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">docker</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> compose</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> up</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -d</span></span></code></pre></div><p>⚠️ <strong>Do NOT manually rotate <code>API_KEY_PEPPER</code> on a populated install.</strong> The auto-rotation in <code>utils/env_check.py</code> deliberately declines to touch the pepper when the database has users — rotating it would invalidate every Argon2 password hash and every Fernet-encrypted broker auth/feed token / TradingView API key, none of which can be recovered. If you genuinely need to rotate the pepper (rare), use the dedicated migration which handles re-encryption and the required password reset:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">uv</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> python</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> upgrade/rotate_pepper.py</span></span></code></pre></div><p>After applying the APP_KEY-only migration, <code>_generate_keys_on_first_run</code> takes the silent fast path (APP_KEY no longer in <code>COMPROMISED_APP_KEYS</code>) and the container boots cleanly. Browser sessions need to log in again — by design, that&#39;s how APP_KEY rotation prevents anyone with the leaked sample key from forging your sessions.</p><hr><p><strong>Contributors</strong></p><ul><li><strong>@marketcalls (Rajandran)</strong> — release management, GTT order implementation for Zerodha and Dhan (#1322), Telegram <code>/stoppython</code> command + <code>/closeall</code> enhancement (#1231), Historify Parquet aggregation fix (#917), codebase-wide bare-except sweep (#1039), critical Docker <code>.env</code> <code>:ro</code> hotfix.</li></ul><hr><p><strong>Links</strong></p><ul><li><strong>Repository</strong>: <a href="https://github.com/wesoftcorp/tradeboard-docs" target="_blank" rel="noreferrer">https://github.com/wesoftcorp/tradeboard-docs</a></li><li><strong>Documentation</strong>: <a href="https://docs.algo.wesoftcorp.com" target="_blank" rel="noreferrer">https://docs.algo.wesoftcorp.com</a></li><li><strong>Discord</strong>: <a href="https://www.tradeboard.in/discord" target="_blank" rel="noreferrer">https://www.tradeboard.in/discord</a></li><li><strong>Issue tracker</strong>: <a href="https://github.com/wesoftcorp/tradeboard-docs/issues" target="_blank" rel="noreferrer">https://github.com/wesoftcorp/tradeboard-docs/issues</a></li></ul><hr><h2 id="" tabindex="-1"><a class="header-anchor" href="#" aria-label="Permalink to &quot;&quot;">​</a></h2>`,63)])])}const u=o(i,[["render",n]]);export{g as __pageData,u as default};
